fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 1.0) {
        val formatted = if (seconds % 1.0 == 0.0) {
            seconds.toLong().toString()
        } else {
            String.format(java.util.Locale.US, "%.1f", seconds).trimEnd('0').trimEnd('.')
        }
        "${formatted}s"
    } else {
        val denominator = (1.0 / seconds).toLong()
        // Cap extremely high denominators to avoid overflow and unreadable values
        val cappedDenom = denominator.coerceIn(1L, 2000L)
        "1/${cappedDenom}s"
    }
